// The contract between the app shell and a module group. Each src/modules/<group>/index.ts exports
// one `ModuleDef`. Foundation-owned: module agents do not edit this file.

import type { ReactNode } from "react"
import type { LucideIcon } from "lucide-react"
import type { ModuleGroup } from "@/data/modules"
import type { Built } from "@/data/screens"
import type { SliceDef } from "@/store/core"
import type { SliceStates } from "@/store/types"

export interface ModuleRoute {
  /** react-router path, e.g. "/inventory/items/:id". Use the registry's path for registry screens. */
  path: string
  element: ReactNode
  /** "office" (default): sidebar + context bar. "kiosk": full-screen floor-touch, no navigation. */
  layout?: "office" | "kiosk"
  /** Registry screen this route renders (for the context bar and /coverage). */
  screenId?: string
}

/** Extra sidebar entries beyond the registry's own (the registry already lists every screen). */
export interface NavEntry {
  to: string
  label: string
  icon?: LucideIcon
  /** The PRD module section the entry sits under. */
  module: string
}

export interface ModuleDef {
  group: ModuleGroup
  routes: ModuleRoute[]
  nav: NavEntry[]
  slices: SliceDef<keyof SliceStates>[]
  /** Screens this module has built, overriding the registry baseline on /coverage. */
  built: Partial<Record<string, Built>>
  /** Optional section shown on WF-INBOX under the shared queue (legacy module-specific items). */
  inboxSection?: { title: string; element: ReactNode }
}
